import{_ as t,o as i,c as o,ag as n}from"./chunks/framework.D9ghT4bC.js";const a="/Unciv/assets/1778417407140.BQp-ABK7.png",r="/Unciv/assets/1778417421124.BggyvfvK.png",s="/Unciv/assets/1778417482159.BAeDu30I.png",l="/Unciv/assets/1778417521851.BmBobuVW.png",d="/Unciv/assets/1778417769315.4Z0fVW0T.png",c="/Unciv/assets/1778417725003.BptUUT3j.png",v=JSON.parse('{"title":"Emperors and Deities (EnD) Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"Community/Mods/Emperors-and-Deities/index.md","filePath":"Community/Mods/Emperors-and-Deities/index.md"}'),u={name:"Community/Mods/Emperors-and-Deities/index.md"};function p(h,e,m,g,y,b){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="emperors-and-deities-end-introduction" tabindex="-1">Emperors and Deities (EnD) Introduction <a class="header-anchor" href="#emperors-and-deities-end-introduction" aria-label="Permalink to &quot;Emperors and Deities (EnD) Introduction&quot;">​</a></h1><h2 id="about-end" tabindex="-1">About EnD <a class="header-anchor" href="#about-end" aria-label="Permalink to &quot;About EnD&quot;">​</a></h2><p>Emperors and Deities (帝王和神明) has neither emperors nor deities — it&#39;s a large-scale ruleset reset mod that overturns how Unciv/Civ V plays. It includes:</p><ul><li><p><strong>Diverse in-game path choices</strong>: policies, religion, historical governments, events. It borrows from Civ VII and Humankind mechanics, but restructured with personal understanding. Choose a region at the start, and all the peoples and civilizations of this colorful land answer to you. (Post-Medieval content under construction.)</p><p><img src="'+a+'" alt="1778417407140"></p><p><img src="'+r+'" alt="1778417421124"></p></li><li><p><strong>Fully refined unit and building mechanics</strong>: units and buildings are not just massively increased in number, but also have detailed categories and Tag support, closely tied to in-game paths. Do you hand military power to hereditary military aristocrats, or push professional-army reform?</p><p><img src="'+s+'" alt="1778417482159"></p></li><li><p><strong>Fully refined tech tree</strong>: from Neolithic starting techs to line infantry of the Imperial era, from Industrial-era telegraphs to Information-era data centers. EnD&#39;s tech tree covers many areas the original doesn&#39;t, including papermaking, cement, fixed ammunition, and more. <s>And basically every tech is juicy.</s> (Electricity-Future eras currently under construction.)</p><p><img src="'+l+'" alt="1778417521851"></p></li><li><p><strong>Happiness mechanic reset</strong>: the backbone of your Golden Age is no longer mere luxury resources, but the windfall profits they bring. Luxuries no longer provide happiness directly; a new municipal building tree, medical building tree, and other infrastructure determine the difficulty of city governance. Fully assimilating cities also requires significant preparation.</p></li><li><p><strong>All-new stability mechanic</strong>: unhappiness triggers negative events that hurt your stability, then rebels and debuffs bloom in both directions. Only by spending your accumulated influence can you turn the tide. Of course, building sound municipal governance is the real cure.</p><p><img src="'+d+'" alt="1778417769315"></p></li><li><p><strong>More little touches</strong>: move surplus population/resources from one city to another? Sure! Make Shang defeat Zhou, or Harappa defeat the Aryans? Up to you. Even blank civs can enjoy most of the content through in-game growth.</p><p><img src="'+c+'" alt="1778417725003"></p></li></ul><h3 id="core-philosophy" tabindex="-1">Core philosophy <a class="header-anchor" href="#core-philosophy" aria-label="Permalink to &quot;Core philosophy&quot;">​</a></h3><blockquote><p>&quot;能改的全部动了。&quot; - CX61 (&quot;Everything that could be changed, was changed.&quot;)</p></blockquote><p>The mod is faithful to historical accuracy — not as endless unbounded detail, but selecting what fits Civ&#39;s hex-grid gameplay and refining it, so players experience a fresh side of the Civilization series.</p><h3 id="quick-links" tabindex="-1">Quick links <a class="header-anchor" href="#quick-links" aria-label="Permalink to &quot;Quick links&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Mod resources</p><ul><li><a href="https://github.com/chenxing61/Emperors-and-Deities" target="_blank" rel="noreferrer">GitHub repository</a></li></ul></div><h3 id="join-the-community-urgent" tabindex="-1">Join the community (urgent) <a class="header-anchor" href="#join-the-community-urgent" aria-label="Permalink to &quot;Join the community (urgent)&quot;">​</a></h3><p>For suggestions or issues, join our QQ group:</p><p><a href="https://qm.qq.com/q/FutBLHn2M4" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/QQ%E7%BE%A4-%E7%82%B9%E5%87%BB%E5%8A%A0%E5%85%A5-green?logo=tencent-qq" alt="QQ group"></a></p><p>Or the Discord server:</p><p><a href="https://discord.gg/EYG6hT3W7N" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/1415865496758259744?label=Discord&amp;color=blue" alt="Discord"></a></p><h3 id="anyway-please-try-the-mod-nobody-plays-no-balance-tuning-and-no-qol" tabindex="-1">Anyway, please try the mod! Nobody plays = no balance tuning and no QoL!!! <a class="header-anchor" href="#anyway-please-try-the-mod-nobody-plays-no-balance-tuning-and-no-qol" aria-label="Permalink to &quot;Anyway, please try the mod! Nobody plays = no balance tuning and no QoL!!!&quot;">​</a></h3><h3 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h3><ol><li>Download the latest mod files</li><li>Put the mod folder into the game&#39;s <code>mods/</code> directory</li><li>Enable Emperors and Deities in game settings</li><li>Start a new game to play</li><li>Or, if you have GitHub access, download it directly in-game.</li></ol><div class="warning custom-block"><p class="custom-block-title">Note</p><ul><li>The mod only supports new games; it is incompatible with existing saves</li><li>Standard speed is recommended for the best experience</li></ul></div><h3 id="thanks" tabindex="-1">Thanks <a class="header-anchor" href="#thanks" aria-label="Permalink to &quot;Thanks&quot;">​</a></h3><p>Thanks to all players and developers who contributed to the mod!</p><p>Special thanks to:</p><ul><li>The Unciv development team for the excellent game platform (Yarim and other hard-working devs)</li><li>All players who tested and gave feedback</li><li>The Unciv community&#39;s support (the modding masters)</li><li>Community members who provided translations</li><li>Bucketeer for art support</li><li>And you, reading this!</li></ul>',22)])])}const k=t(u,[["render",p]]);export{v as __pageData,k as default};
